={{ (() => {
  const CARDAPIO = [
    { numero: 1, nome: 'Duplo Costela Burger', preco: 46.90, aliases: ['duplo costela burger', 'duplo costela', 'costela duplo'] },
    { numero: 2, nome: 'Costela Burger', preco: 38.90, aliases: ['costela burger', 'burger de costela', 'costela burguer'] },
    { numero: 3, nome: 'Teriyaki Burger', preco: 44.90, aliases: ['teriyaki burger', 'teriyaki'] },
    { numero: 4, nome: 'Xis Carne', preco: 34.90, aliases: ['xis carne'] },
    { numero: 5, nome: 'Xis Frango', preco: 36.90, aliases: ['xis frango'] },
    { numero: 6, nome: 'Xis Bacon', preco: 39.90, aliases: ['xis bacon'] },
    { numero: 7, nome: 'Xis Coração', preco: 42.90, aliases: ['xis coração', 'xis coracao'] },
    { numero: 8, nome: 'Batata Grande com Cheddar e Bacon', preco: 45.90, aliases: ['batata grande com cheddar e bacon', 'batata grande cheddar bacon', 'batata cheddar bacon'] },
    { numero: 9, nome: 'Batata Grande', preco: 42.90, aliases: ['batata grande'] },
    { numero: 10, nome: 'Batata Média', preco: 22.90, aliases: ['batata média', 'batata media'] },
    { numero: 11, nome: 'Coca-Cola Zero 2L', preco: 16.90, aliases: ['coca-cola zero 2 litros', 'coca cola zero 2 litros', 'coca zero 2 litros', 'coca-cola zero', 'coca cola zero', 'coca zero'] },
    { numero: 12, nome: 'Coca-Cola 2L', preco: 19.90, aliases: ['coca-cola 2 litros', 'coca cola 2 litros', 'coca 2 litros', 'coca-cola 2l', 'coca 2l'] },
    { numero: 13, nome: 'Coca-Cola lata', preco: 8.90, aliases: ['coca-cola lata', 'coca cola lata', 'coca lata', 'coquinha'] },
    { numero: 14, nome: 'Guaraná Antártica 2L', preco: 14.90, aliases: ['guaraná antártica', 'guarana antartica'] },
    { numero: 15, nome: 'Guaraná Fruki 2L', preco: 12.90, aliases: ['guaraná fruki', 'guarana fruki'] },
    { numero: 16, nome: 'Água sem gás', preco: 5.00, aliases: ['água sem gás', 'agua sem gas'] },
    { numero: 17, nome: 'Água com gás', preco: 5.00, aliases: ['água com gás', 'agua com gas'] },
    { numero: 18, nome: 'Heineken lata', preco: 12.90, aliases: ['heineken'] },
    { numero: 19, nome: 'Chocolate Lacta Laka 80g', preco: 12.90, aliases: ['chocolate lacta laka', 'lacta laka', 'laka'] },
    { numero: 20, nome: 'Chocolate Lacta Shot 80g', preco: 12.90, aliases: ['chocolate lacta shot', 'lacta shot', 'chocolate shot'] },
    { numero: 21, nome: 'Chocolate Lacta ao leite 80g', preco: 12.90, aliases: ['chocolate lacta ao leite', 'lacta ao leite', 'chocolate ao leite'] },
    { numero: 22, nome: 'Chocolate Neugebauer preto e branco 80g', preco: 12.90, aliases: ['chocolate neugebauer', 'neugebauer preto e branco', 'neugebauer'] }
  ];

  const fmt = (n) => n.toFixed(2);
  const escapeRegex = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

  const numeroCliente = $('Extrair mensagem').item.json.numero;
  const textoOriginal = $('Extrair mensagem').item.json.texto_original || '';
  const textoLower = ($('Extrair mensagem').item.json.texto_lower || '').toString().trim();

  const carrinhoItens = Array.isArray($json.itens) ? $json.itens : [];
  let aguardando = $json.aguardando || null;

  // Se a última interação foi há mais de 5 horas, trata como um atendimento novo
  const ultimaInteracao = $('Buscar carrinho').item.json.updated_at;
  const horasDesdeUltimaInteracao = ultimaInteracao ? ($now.toMillis() - new Date(ultimaInteracao).getTime()) / 3600000 : Infinity;
  if (horasDesdeUltimaInteracao > 5) {
    aguardando = null;
    carrinhoItens.length = 0;
  }

  const montaCardapioTexto = () => {
    const linhas = CARDAPIO.map(p => `*${p.numero}.* ${p.nome} — R$ ${fmt(p.preco)}`).join('\n');
    return `🍔 *Cardápio Tompytyo Lanches*\n\n${linhas}\n\nPra pedir, digite o *número* do item que deseja (ex: "2"). Depois eu pergunto a quantidade!\n\n📱 Prefere ver com fotos? Nosso catálogo: https://wa.me/c/555195886356`;
  };

  const resumoCarrinho = (itens) => itens.map(i => `${i.quantidade}x ${i.nome} - R$ ${fmt(i.subtotal)}`).join('\n');
  const totalCarrinho = (itens) => itens.reduce((s, i) => s + i.subtotal, 0);

  const base = {
    resposta: '',
    pedido_fechado: false,
    atendente_solicitado: false,
    pedido_texto_interno: '',
    novo_itens: carrinhoItens,
    novo_aguardando: aguardando
  };

  // 1. Remover item específico do carrinho
  const matchRemover = textoLower.match(/^(remover|remova|tirar|tira|excluir|apagar)\s+(.+)$/i);
  if (matchRemover && carrinhoItens.length) {
    const alvo = matchRemover[2].trim();
    const novosItens = carrinhoItens.map(i => ({ ...i }));
    let idx = -1;
    if (/^\d+$/.test(alvo)) {
      idx = novosItens.findIndex(i => i.numero === parseInt(alvo, 10));
    }
    if (idx === -1) {
      idx = novosItens.findIndex(i => i.nome.toLowerCase().includes(alvo));
    }
    if (idx !== -1) {
      const removido = novosItens.splice(idx, 1)[0];
      return {
        ...base,
        resposta: novosItens.length
          ? `Removido: ${removido.nome} ❌\n\n${resumoCarrinho(novosItens)}\n\n*Total até agora: R$ ${fmt(totalCarrinho(novosItens))}*\n\nQuer mais alguma coisa? Digite *cardápio*, *remover <item>* ou *fechar pedido*. 😊`
          : `Removido: ${removido.nome} ❌\n\nSeu carrinho ficou vazio. Digite *cardápio* pra ver as opções! 🍔`,
        novo_itens: novosItens
      };
    }
    return {
      ...base,
      resposta: `Não encontrei "${alvo}" no seu carrinho 🤔\n\n${resumoCarrinho(carrinhoItens)}\n\nDigite *cardápio* pra ver os números dos itens.`
    };
  }

  // 2. Limpar o carrinho inteiro
  if (/limpar carrinho|esvaziar carrinho|zerar carrinho|cancelar carrinho/i.test(textoLower)) {
    return {
      ...base,
      resposta: 'Carrinho esvaziado! 🧹 Digite *cardápio* pra começar de novo.',
      novo_itens: [],
      novo_aguardando: null
    };
  }

  // Modo despedida (logo após fechar um pedido): trata cumprimentos/agradecimentos como
  // encerramento de papo, não como um novo "seja bem-vindo", até o cliente iniciar algo novo
  if (aguardando && aguardando.modo === 'despedida') {
    const novoAssunto = /cardapio|cardápio|menu|ver op[çc][õo]es|atendente|falar com|remover|remova|tirar|tira|excluir|apagar|limpar carrinho|esvaziar carrinho|zerar carrinho|cancelar carrinho|^\d+$/i.test(textoLower);
    if (!novoAssunto) {
      const hora = $now.hour;
      let saudacaoHorario;
      if (hora >= 5 && hora < 12) saudacaoHorario = 'Bom dia';
      else if (hora >= 12 && hora < 18) saudacaoHorario = 'Boa tarde';
      else saudacaoHorario = 'Boa noite';
      return {
        ...base,
        resposta: `Eu que agradeço! 🙏 ${saudacaoHorario}! Foi um prazer te atender, até a próxima! 👋`,
        novo_aguardando: aguardando
      };
    }
    aguardando = null;
    base.novo_aguardando = null;
  }

  // Resposta à oferta de chocolate feita antes de fechar o pedido
  if (aguardando && aguardando.modo === 'oferta_chocolate') {
    const negou = /^(n[ãa]o|nops?)\b|sem chocolate|n[ãa]o quero|s[óo] isso|pode fechar|assim mesmo|deixa assim/i.test(textoLower)
      || /fechar pedido|finalizar|confirmar pedido|concluir/i.test(textoLower);
    const CHOCOLATES = CARDAPIO.filter(p => p.numero >= 19 && p.numero <= 22);
    let escolhido = null;
    if (/^\d+$/.test(textoLower)) {
      escolhido = CHOCOLATES.find(p => p.numero === parseInt(textoLower, 10));
    }
    if (!escolhido) {
      escolhido = CHOCOLATES.find(p => p.aliases.some(a => textoLower.includes(a)));
    }

    let itensFinais = carrinhoItens.map(i => ({ ...i }));
    if (escolhido) {
      const existente = itensFinais.find(i => i.numero === escolhido.numero);
      if (existente) {
        existente.quantidade += 1;
        existente.subtotal = existente.quantidade * existente.precoUnit;
      } else {
        itensFinais.push({ numero: escolhido.numero, nome: escolhido.nome, quantidade: 1, precoUnit: escolhido.preco, subtotal: escolhido.preco });
      }
    } else if (!negou) {
      return {
        ...base,
        resposta: `Não entendi 🤔 Quer adicionar algum chocolate do nosso catálogo (https://wa.me/c/555195886356)? Me diz o nome dele, ou digite *não* pra fechar sem.`,
        novo_itens: carrinhoItens,
        novo_aguardando: aguardando
      };
    }

    const total = totalCarrinho(itensFinais);
    const linhas = resumoCarrinho(itensFinais);
    const textoInterno = `🆕 *Novo pedido pelo WhatsApp*\n\nCliente: ${numeroCliente}\n\n${linhas}\n\n*Total: R$ ${fmt(total)}*`;
    return {
      ...base,
      resposta: `✅ *Pedido confirmado!*\n\n${linhas}\n\n*Total: R$ ${fmt(total)}*\n\nEm instantes alguém vai confirmar com você. Obrigado! 😊`,
      pedido_fechado: true,
      pedido_texto_interno: textoInterno,
      novo_itens: [],
      novo_aguardando: { modo: 'despedida' }
    };
  }

  // 3. Esperando quantidade de um item já escolhido
  if (aguardando) {
    const match = textoLower.match(/\d+/);
    const qtd = match ? Math.max(1, parseInt(match[0], 10)) : 1;
    const novosItens = carrinhoItens.map(i => ({ ...i }));
    const existente = novosItens.find(i => i.numero === aguardando.numero);
    if (existente) {
      existente.quantidade += qtd;
      existente.subtotal = existente.quantidade * existente.precoUnit;
    } else {
      novosItens.push({ numero: aguardando.numero, nome: aguardando.nome, quantidade: qtd, precoUnit: aguardando.preco, subtotal: qtd * aguardando.preco });
    }
    return {
      ...base,
      resposta: `Adicionado! ✅\n\n${resumoCarrinho(novosItens)}\n\n*Total até agora: R$ ${fmt(totalCarrinho(novosItens))}*\n\nQuer mais alguma coisa? Digite *cardápio*, *remover <item>* ou *fechar pedido* pra finalizar. 😊`,
      novo_itens: novosItens,
      novo_aguardando: null
    };
  }

  // Saudação (bom dia / boa tarde / boa noite)
  if (/\bbom\s*dia\b|\bboa\s*tarde\b|\bboa\s*noite\b/i.test(textoLower)) {
    const hora = $now.hour;
    let saudacaoHorario;
    if (hora >= 5 && hora < 12) saudacaoHorario = 'Bom dia';
    else if (hora >= 12 && hora < 18) saudacaoHorario = 'Boa tarde';
    else saudacaoHorario = 'Boa noite';
    return {
      ...base,
      resposta: `${saudacaoHorario}! 👋 Seja bem-vindo(a) à Tompytyo Lanches!\n\nDigite *cardápio* pra ver nosso menu ou pergunte o *horário*. 😊`
    };
  }

  // 2. Atendente / suporte humano
  if (/atendente|falar com (uma )?pessoa|falar com algu[ée]m|falar com humano|quero um humano|suporte humano|n[ãa]o quero (falar com o )?(robo|bot)|humano por favor|reclama[çc][ãa]o|problema com (o )?(meu )?pedido|cancelar pedido/i.test(textoLower)) {
    return {
      ...base,
      resposta: '🙋 Entendido! Já vou chamar alguém da nossa equipe pra te atender por aqui. Só mais um instante, por favor! 😊',
      atendente_solicitado: true
    };
  }

  // 3. Cardápio
  if (/cardapio|cardápio|menu|ver op[çc][õo]es/i.test(textoLower)) {
    return { ...base, resposta: montaCardapioTexto() };
  }

  // 4. Horário
  if (/horario|horário|abrem|fecham|funciona/i.test(textoLower)) {
    return {
      ...base,
      resposta: '⏰ *Nosso horário de funcionamento*\n\nSegunda a quinta: 18h às 23h59\nSexta: 18h às 2h (madrugada de sábado)\nSábado: 10h às 2h (madrugada de domingo)\nDomingo: 10h às 21h\n\nQue tal aproveitar e dar uma olhadinha no nosso *cardápio*? 🍔 É só digitar *cardápio*!'
    };
  }


  // 5. Cliente não quer fazer pedido (declinou)
  if (/n[ãa]o\s*(quero|vou|pretendo|desejo)\s*(fazer\s*)?(o\s*)?pedido|n[ãa]o\s*quero\s*pedir|n[ãa]o\s*vou\s*pedir|s[óo]\s*(estou\s*|t[ôo]\s*)?(olhando|dando uma olhada|espiando|pesquisando)|talvez depois|depois eu (pe[çc]o|volto)|n[ãa]o,?\s*obrigad[oa]/i.test(textoLower)) {
    const hora = $now.hour;
    let saudacaoHorario;
    if (hora >= 5 && hora < 12) saudacaoHorario = 'Bom dia';
    else if (hora >= 12 && hora < 18) saudacaoHorario = 'Boa tarde';
    else saudacaoHorario = 'Boa noite';
    return {
      ...base,
      resposta: `${saudacaoHorario}! 😊 Tudo bem, sem problema! Agradecemos por dar uma olhadinha no nosso cardápio. Quando quiser fazer seu pedido, é só chamar por aqui. Até logo! 👋`,
      novo_aguardando: { modo: 'despedida' }
    };
  }

  // 6. Fechar pedido
  if (/fechar pedido|finalizar|pode fechar|confirmar pedido|s[óo] isso|é s[óo]|concluir/i.test(textoLower)) {
    if (!carrinhoItens.length) {
      return { ...base, resposta: 'Seu carrinho está vazio! Digite *cardápio* pra ver as opções. 🍔' };
    }
    const jaTemChocolate = carrinhoItens.some(i => i.numero >= 19 && i.numero <= 22);
    if (!jaTemChocolate) {
      return {
        ...base,
        resposta: `Antes de fechar... 🍫 Temos chocolates no nosso catálogo!\n\n📱 Dá uma olhada: https://wa.me/c/555195886356\n\nSe quiser adicionar algum, me diz o nome dele. Ou digite *não* pra fechar sem.`,
        novo_aguardando: { modo: 'oferta_chocolate' }
      };
    }
    const total = totalCarrinho(carrinhoItens);
    const linhas = resumoCarrinho(carrinhoItens);
    const textoInterno = `🆕 *Novo pedido pelo WhatsApp*\n\nCliente: ${numeroCliente}\n\n${linhas}\n\n*Total: R$ ${fmt(total)}*`;
    return {
      ...base,
      resposta: `✅ *Pedido confirmado!*\n\n${linhas}\n\n*Total: R$ ${fmt(total)}*\n\nEm instantes alguém vai confirmar com você. Obrigado! 😊`,
      pedido_fechado: true,
      pedido_texto_interno: textoInterno,
      novo_itens: [],
      novo_aguardando: { modo: 'despedida' }
    };
  }

  // 7. Cliente digitou só um número -> escolheu um item do cardápio pelo número
  if (/^\d+$/.test(textoLower)) {
    const escolhido = CARDAPIO.find(p => p.numero === parseInt(textoLower, 10));
    if (escolhido) {
      return {
        ...base,
        resposta: `Quantas unidades de *${escolhido.nome}* você quer? 🔢`,
        novo_aguardando: { numero: escolhido.numero, nome: escolhido.nome, preco: escolhido.preco }
      };
    }
  }

  // 8. Tenta reconhecer itens em texto livre (nomes do cardápio)
  let textoRestante = textoLower;
  const encontrados = [];
  const cardapioOrdenado = [...CARDAPIO].sort((a, b) => b.aliases[0].length - a.aliases[0].length);
  for (const produto of cardapioOrdenado) {
    let quantidade = 0;
    for (const alias of produto.aliases) {
      const aliasEscapado = escapeRegex(alias);
      const comQuantidade = new RegExp('(\\d+)\\s*x?\\s*' + aliasEscapado, 'gi');
      let m;
      while ((m = comQuantidade.exec(textoRestante)) !== null) {
        quantidade += parseInt(m[1], 10);
        textoRestante = textoRestante.replace(m[0], ' ');
      }
      const semQuantidade = new RegExp('\\b' + aliasEscapado + '\\b', 'gi');
      while ((m = semQuantidade.exec(textoRestante)) !== null) {
        quantidade += 1;
        textoRestante = textoRestante.replace(m[0], ' ');
      }
    }
    if (quantidade > 0) {
      encontrados.push({ numero: produto.numero, nome: produto.nome, quantidade, precoUnit: produto.preco, subtotal: quantidade * produto.preco });
    }
  }

  if (encontrados.length) {
    const novosItens = carrinhoItens.map(i => ({ ...i }));
    for (const novo of encontrados) {
      const existente = novosItens.find(i => i.numero === novo.numero);
      if (existente) {
        existente.quantidade += novo.quantidade;
        existente.subtotal = existente.quantidade * existente.precoUnit;
      } else {
        novosItens.push(novo);
      }
    }
    return {
      ...base,
      resposta: `Adicionado! ✅\n\n${resumoCarrinho(novosItens)}\n\n*Total até agora: R$ ${fmt(totalCarrinho(novosItens))}*\n\nQuer mais alguma coisa? Digite *cardápio*, *remover <item>* ou *fechar pedido* pra finalizar. 😊`,
      novo_itens: novosItens
    };
  }

  // 9. Confirmações curtas (aguardo, ok, etc)
  const ehConfirmacaoCurta = /\b(ok(ay)?|blz|beleza|t[áa]\s*bom|t[áa]\s*certo|certo|entendid[oa]|combinado|show|valeu|obrigad[oa]s?|obg|aguard\w*|esper\w*|tranquilo|de boa|perfeito|top|joia)\b/i.test(textoLower);
  if (ehConfirmacaoCurta) {
    return { ...base, resposta: 'Combinado! 😊 Só mais um instante que já vamos preparar tudo certinho.' };
  }

  // 10. Fallback geral
  return {
    ...base,
    resposta: 'Oi! 👋 Aqui você pode:\n\n📋 Digitar *cardápio* pra ver o menu\n⏰ Perguntar o *horário*\n🙋 Pedir pra *falar com atendente*\n\nÉ só escrever!'
  };
})() }}
